<script setup lang="ts">
import {authClient}from"~/lib/auth-client";definePageMeta({layout:false});const route=useRoute();const email=ref("");const password=ref("");const loading=ref(false);const error=ref("");
async function login(){loading.value=true;error.value="";const result=await authClient.signIn.email({email:email.value,password:password.value});if(result.error){error.value="Email atau password admin tidak cocok.";loading.value=false;return;}const session=await $fetch("/api/session");if(!session.isAdmin){await authClient.signOut();error.value="Akun tidak memiliki role admin.";loading.value=false;return;}const next=String(route.query.next||"/admin");await navigateTo(next.startsWith("/")&&!next.startsWith("//")?next:"/admin");}
useSeoMeta({title:"Admin Login"});
</script>
<template><main class="grid min-h-screen place-items-center bg-[#071a3d] p-5"><form class="surface w-full max-w-md p-8" @submit.prevent="login"><div class="text-center"><img src="/logo-jwlab-studio.webp" class="mx-auto h-28 w-auto" alt="JWLAB STUDIO"><p class="eyebrow mt-2">Control panel</p><h1 class="mt-2 text-2xl font-black">Administrator</h1></div><label class="field-label mt-8">Email<input v-model="email" type="email" autocomplete="username" class="field" required></label><label class="field-label mt-4">Password<input v-model="password" type="password" autocomplete="current-password" class="field" required></label><p v-if="error" class="mt-3 text-sm text-red-600">{{error}}</p><AppButton type="submit" class="mt-6 w-full" :disabled="loading">{{loading?'Memeriksa...':'Masuk admin'}}</AppButton><NuxtLink to="/" class="mt-5 block text-center text-xs font-bold text-slate-500">Kembali ke toko</NuxtLink></form></main></template>
